// Text helpers of the emitters. Every generated file starts with the same header and holds no time, path or host
// (I-5).

export type Files = Map<string, string>;

export const header = (comment: string): string =>
  `${comment} Generated by bindgen from the interface contract; do not edit. Run make bindings to write it again.`;

export const pyHeader = (): string => header('#');

// A Rust string literal.
export const rustString = (text: string): string => JSON.stringify(text);

// A Python string literal with only ASCII in the source.
export function pyString(text: string): string {
  let out = '"';
  for (const unit of text) {
    const code = unit.codePointAt(0) ?? 0;
    if (unit === '"' || unit === '\\') out += `\\${unit}`;
    else if (code >= 0x20 && code < 0x7f) out += unit;
    else if (code <= 0xff) out += `\\x${code.toString(16).padStart(2, '0')}`;
    else if (code <= 0xffff) out += `\\u${code.toString(16).padStart(4, '0')}`;
    else out += `\\U${code.toString(16).padStart(8, '0')}`;
  }
  return `${out}"`;
}

// A JavaScript string literal with only ASCII in the source; lone surrogates stay as escapes.
export function jsString(text: string): string {
  let out = "'";
  for (let i = 0; i < text.length; i += 1) {
    const unit = text.charCodeAt(i);
    const char = text.charAt(i);
    if (char === "'" || char === '\\') out += `\\${char}`;
    else if (unit >= 0x20 && unit < 0x7f) out += char;
    else out += `\\u${unit.toString(16).padStart(4, '0')}`;
  }
  return `${out}'`;
}

// A PHP double-quoted string literal whose bytes are the given bytes (T-1 latin1, B-3).
export function phpBytes(bytes: Iterable<number>): string {
  let out = '"';
  for (const byte of bytes) {
    const char = String.fromCharCode(byte);
    if (char === '"' || char === '\\' || char === '$') out += `\\${char}`;
    else if (byte >= 0x20 && byte < 0x7f) out += char;
    else out += `\\x${byte.toString(16).padStart(2, '0')}`;
  }
  return `${out}"`;
}

export const phpText = (text: string): string => phpBytes(new TextEncoder().encode(text));
export const phpLatin1 = (text: string): string => phpBytes([...text].map((c) => c.codePointAt(0) ?? 0));

// The helper functions of a block of Rust items (each a function with its doc comment, the items separated by blank
// lines and holding none) that `code` calls, directly or through another helper, in their order in the block; a crate holds no unused
// helper, because its lints deny dead code.
export function usedHelpers(block: string, code: string): string {
  const items = block.split(/\n[ \t]*\n/).map((item) => item.trim()).filter((item) => item !== '');
  const named = items.map((item) => ({ item, name: /^(?:\/\/\/[^\n]*\n)*(?:fn|trait) ([A-Za-z_0-9]+)/.exec(item)?.[1] ?? '' }));
  const used = new Set<string>();
  // A helper is used where its name is a word of the code, called or passed; comments do not count.
  const strip = (text: string): string => text.replace(/\/\/[^\n]*/g, '');
  let frontier = strip(code);
  for (;;) {
    const added = named.filter(({ name }) => !used.has(name) && new RegExp(`\\b${name}\\b`).test(frontier));
    if (added.length === 0) break;
    for (const { name } of added) used.add(name);
    frontier = strip(added.map(({ item }) => item).join('\n'));
  }
  return named.filter(({ name }) => used.has(name)).map(({ item }) => `\n${item}\n`).join('');
}

// R-1 and K-2: the lints of every generated crate. They are the generated crate's own, not the workspace's, because a
// binding framework's macros expand to unsafe code, which a repository's workspace may forbid for its core; the
// generated code's own unsafe blocks carry an allow with its reason.
export const GENERATED_LINTS = `[lints.rust]
warnings = "deny"
unsafe_code = "deny"
unused_must_use = "deny"

[lints.clippy]
all = { level = "deny", priority = -1 }
allow_attributes_without_reason = "deny"
unwrap_used = "deny"
expect_used = "deny"
let_underscore_must_use = "deny"
let_underscore_untyped = "deny"
map_err_ignore = "deny"
as_conversions = "deny"
`;

// T-1: an integer return (uint, int, int64) may be a narrower Rust integer, which the generated code widens with From;
// a parameter is the type of the table. Each trait takes the integer and a reference to it, as a return is read in
// either form. The two methods have their own names because u8, u16 and u32 implement both traits.
export const WIDEN = `
/// T-1: a uint return is u64 or a narrower unsigned integer, which widens with From.
trait WideUint {
    fn widen_uint(self) -> u64;
}
macro_rules! wide_uint {
    ($($t:ty),*) => {$(
        impl WideUint for $t {
            fn widen_uint(self) -> u64 { u64::from(self) }
        }
        impl WideUint for &$t {
            fn widen_uint(self) -> u64 { u64::from(*self) }
        }
    )*};
}
wide_uint!(u8, u16, u32, u64);

/// T-1: an int or int64 return is i64 or a narrower integer, which widens with From.
trait WideInt {
    fn widen_int(self) -> i64;
}
macro_rules! wide_int {
    ($($t:ty),*) => {$(
        impl WideInt for $t {
            fn widen_int(self) -> i64 { i64::from(self) }
        }
        impl WideInt for &$t {
            fn widen_int(self) -> i64 { i64::from(*self) }
        }
    )*};
}
wide_int!(i8, i16, i32, i64, u8, u16, u32);
`;

// A closure that only calls a function with its own parameters is the function itself (clippy redundant_closure).
export function closure(params: string[], body: string): string {
  const call = /^([a-z_][a-z_0-9]*)\((.*)\)$/.exec(body);
  if (call !== null && call[2] === params.join(', ')) return call[1] ?? '';
  return `|${params.join(', ')}| ${body}`;
}

// An optional value as Option<&T>, whether the Rust code holds the Option or a reference to it (T-1: a return is read
// in either form).
export const optionRef = (value: string): string => (value.startsWith('&') ? `${value.slice(1)}.as_ref()` : `${value}.as_ref()`);
